# This code was generated by Claude Code to produce a test tensor for NVFP4 dequantization. It creates a small tensor with known values, packs it into the safetensors format, and writes it to disk along with the expected dequantized output.

import json
import pathlib
import struct

import ml_dtypes
import numpy as np

OUT = pathlib.Path(__file__).resolve().parent.parent / "src" / "testdata"
ROWS, COLS = 2, 32  # 4 blocks of 16, two per row

# E2M1 codes, one per element. Every block is chosen so that a mistake shows up:
codes = np.array(
    [
        list(range(16)) + list(range(15, -1, -1)),  # row 0: all 16 codes, then reversed (nibble swap is visible)
        list(range(16)) + [7, 15] * 8,  # row 1: all codes on a subnormal scale, then +-6 on the max scale
    ],
    dtype=np.uint8,
)

# E4M3 block scales, shape [rows, cols/16]: every block has a different one
scales = np.array(
    [
        [0x38, 0x3F],  # 1.0, 1.875 (mantissa bits)
        [0x01, 0x7E],  # 2^-9 (smallest subnormal), 448 (max)
    ],
    dtype=np.uint8,
)

# Tensor scale as ModelOpt computes it, amax / (6 * 448). amax = 0.1 is picked so that
# e2m1 * (e4m3 * scale_2) differs from (e2m1 * e4m3) * scale_2 on some elements (amax = 1 hides it)
scale_2 = np.float32(0.1) / np.float32(6 * 448)

# Pack two codes per byte, element 2k in the low nibble
packed = (codes[:, 0::2] | (codes[:, 1::2] << 4)).astype(np.uint8)

e2m1 = codes.view(ml_dtypes.float4_e2m1fn).astype(np.float32)
e4m3 = np.repeat(scales.view(ml_dtypes.float8_e4m3fn).astype(np.float32), 16, axis=1)
expected = (e2m1 * e4m3) * scale_2
assert expected.dtype == np.float32 and expected.shape == (ROWS, COLS)

# Non-NVFP4 tensors the real checkpoint also has, which the parser must skip or pass through
input_scale = np.float32(0.5)
norm = np.linspace(-1, 1, 8, dtype=np.float32).astype(ml_dtypes.bfloat16)

# Same dtype order as data/model.safetensors: F32, BF16, F8_E4M3, U8
tensors = [
    ("tiny.input_scale", "F32", [], np.array(input_scale).tobytes()),
    ("tiny.weight_scale_2", "F32", [], np.array(scale_2).tobytes()),
    ("tiny.norm.weight", "BF16", [8], norm.tobytes()),
    ("tiny.weight_scale", "F8_E4M3", [ROWS, COLS // 16], scales.tobytes()),
    ("tiny.weight", "U8", [ROWS, COLS // 2], packed.tobytes()),
]

header = {"__metadata__": {"format": "pt"}}
offset = 0
for name, dtype, shape, data in tensors:
    header[name] = {"dtype": dtype, "shape": shape, "data_offsets": [offset, offset + len(data)]}
    offset += len(data)

header_bytes = json.dumps(header, separators=(",", ":")).encode()
header_bytes += b" " * (-len(header_bytes) % 8)  # pad with spaces to 8 bytes, like the reference writer

OUT.mkdir(parents=True, exist_ok=True)
with open(OUT / "tiny_nvfp4.safetensors", "wb") as f:
    f.write(struct.pack("<Q", len(header_bytes)))
    f.write(header_bytes)
    for _, _, _, data in tensors:
        f.write(data)
expected.astype("<f4").tofile(OUT / "tiny_nvfp4.expected.f32")

# Does this tensor tell the two multiplication orders apart?
hoisted = e2m1 * (e4m3 * scale_2)
diff = int(np.sum(expected.view(np.uint32) != hoisted.view(np.uint32)))

np.set_printoptions(linewidth=200)
print(f"wrote {OUT / 'tiny_nvfp4.safetensors'} and tiny_nvfp4.expected.f32")
print(f"scale_2 = {scale_2!r}  packed row 0 = {packed[0].tobytes().hex(' ')}")
print(f"elements where e2m1 * (e4m3 * scale_2) differs: {diff} of {expected.size}")
print(expected)
